INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0039-a04-019-8', 'p0039', 'sanguozhi', 'a04-019', '《三國志·魏書十九》', '魏略曰：丁儀字正禮，沛郡人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0039-a04-019-9', 'p0039', 'sanguozhi', 'a04-019', '《三國志·魏書十九》', '乃令楊脩以倚注遇害，丁儀以希意族滅，哀夫！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0039-a04-021-10', 'p0039', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '」沛國丁儀、丁廙、弘農楊脩、河內苟緯等，亦有文采，而不在此七人之例。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0039-a04-021-11', 'p0039', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '廙著書數十篇，及與丁儀共論刑禮，皆傳於世。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0039-a04-022-12', 'p0039', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '又毛玠、徐弈以剛蹇少黨，而為西曹掾丁儀所不善，儀屢言其短，賴階左右以自全保。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0039-a04-022-13', 'p0039', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '丁儀等為之羽翼，勸臻自結，臻以大義拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0040-a03-035-0', 'p0040', 'houhanshu', 'a03-035', '《後漢書·卷三十五》', '其門人山陽郗慮至御史大夫，東萊王基、清河崔琰著名於世。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0040-a04-001-1', 'p0040', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '魏氏春秋曰：以荀攸為尚書令，涼茂為僕射，毛玠、崔琰、常林、徐奕、何夔為尚書，王粲、杜襲、衞覬、和洽為侍中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0040-a04-006-2', 'p0040', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '孫盛評曰：案魏武謂崔琰曰「昨案貴州戶籍，可得三十萬衆」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0040-a04-011-3', 'p0040', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '崔琰為東曹掾，記讓曰：「徵事邴原、議郎張範，皆秉德純懿，志行忠方，清靜足以厲俗，貞固足以幹事，所謂龍翰鳳翼，國之重寶。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0040-a04-012-4', 'p0040', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '崔琰字季珪，清河東武城人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0040-a04-012-5', 'p0040', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '公忿然曰：「崔琰必欲使孤行刀鋸乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0040-a04-012-6', 'p0040', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '太祖為司空丞相，玠甞為東曹掾，與崔琰並典選舉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0040-a04-012-7', 'p0040', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '崔琰、徐弈，一時清賢，皆以忠信顯於魏朝；丁儀間之，徐弈失位而崔琰被誅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0040-a04-012-8', 'p0040', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '崔琰高格最優，鮑勛秉正無虧，而皆不免其身，惜哉！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0040-a04-023-9', 'p0040', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '時毛玠、崔琰並以忠清幹事，其選用先尚儉節。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0040-a05-001-10', 'p0040', 'jinshu', 'a05-001', '《晉書·卷一》', '尚書清河崔琰與帝兄朗善，亦謂朗曰：「君弟聰亮明允，剛斷英特，非子所及也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0041-a04-001-0', 'p0041', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '於是中軍師王凌、謝亭侯荀攸、前軍師東武亭侯鍾繇、左軍師涼茂、右軍師毛玠、平虜將軍華鄉侯劉勳、建武將軍清苑亭侯劉若、伏波將軍高安侯夏侯惇、揚武將軍都亭侯王忠、奮威將軍樂鄉侯劉展、建忠將軍昌鄉亭侯鮮于輔、奮武將軍安國亭侯程昱、太中大夫都鄉侯賈詡、軍師祭酒千秋亭侯董昭、都亭侯薛洪、南鄉亭侯董蒙、關內侯王粲、傅巽、祭酒王選、袁奐、王朗、張承、任藩、杜襲、中護軍國明亭侯曹洪、中領軍萬歲亭侯韓浩、行驍騎將軍安平亭侯曹仁、領護軍將軍王圖、長史萬潛、謝奐、袁霸等勸進曰：「自古三代，胙臣以土，受命中興，封秩輔佐，皆所以襃功賞德，為國藩衞也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0041-a04-001-1', 'p0041', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '魏氏春秋曰：以荀攸為尚書令，涼茂為僕射，毛玠、崔琰、常林、徐奕、何夔為尚書，王粲、杜襲、衞覬、和洽為侍中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0041-a04-002-2', 'p0041', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '丁亥令曰：「故尚書僕射毛玠、奉常王脩、涼茂、郎中令袁渙、少府謝奐、萬潛、中尉徐奕、國淵等，皆忠直在朝，履蹈仁義，並早即世，而子孫陵遲，惻然愍之，其皆拜子男為郎中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0041-a04-012-3', 'p0041', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '毛玠字孝先，陳留平丘人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0041-a04-012-4', 'p0041', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '尚書傅巽謂夔曰：「人不相好已甚，子友毛玠，玠等儀已害之矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0041-a04-012-5', 'p0041', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '毛玠清公素履，司馬芝忠亮不傾，庶乎不吐剛茹柔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0041-a04-022-6', 'p0041', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '又毛玠、徐弈以剛蹇少黨，而為西曹掾丁儀所不善，儀屢言其短，賴階左右以自全保。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0041-a04-023-7', 'p0041', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '時毛玠、崔琰並以忠清幹事，其選用先尚儉節。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0041-a04-023-8', 'p0041', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '魏國旣建，為侍中，後有白毛玠謗毀太祖，太祖見近臣，怒甚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0042-a03-070-0', 'p0042', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '將軍本以兖州首事，故能平定山東，曹操初從東郡守鮑信等迎領兖州牧，遂進兵破黃巾等，故能平定山東也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0042-a03-074-1', 'p0042', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '及卓將兵至，騎都尉太山鮑信說紹曰：魏書曰：「信，太山陽平人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0042-a03-074-2', 'p0042', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '濟北相鮑信等同時俱起，衆各數萬，以討卓為名。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0042-a04-001-3', 'p0042', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '濟北相鮑信信事見子勛傳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0042-a04-001-4', 'p0042', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '劉岱欲擊之，鮑信諫曰：「今賊衆百萬，百姓皆震恐，士卒無鬬志，不可敵也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0042-a04-006-5', 'p0042', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '先是，進遣騎都尉太山鮑信所在募兵，適至，信謂紹曰：「卓擁彊兵，有異志，今不早圖，將為所制；及其初至疲勞，襲之可禽也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0042-a04-017-6', 'p0042', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '黃巾起，鮑信招合徒衆，禁附從焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a03-074-0', 'p0044', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '蜀志曰：「曹公使張遼及關羽為先鋒，羽望見良麾蓋，策馬刺良萬衆之中，斬其首還，諸將莫能當，遂解白馬圍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-001-1', 'p0044', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '使張遼、關羽前登，擊破，斬良。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-001-2', 'p0044', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '公登高，望虜陳不整，乃縱兵擊之，使張遼為先鋒，虜衆大崩，斬蹋頓及名王已下，胡、漢降者二十餘萬口。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-001-3', 'p0044', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '八月，孫權圍合肥，張遼、李典擊破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-001-4', 'p0044', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '三月，王引軍還，留夏侯惇、曹仁、張遼等屯居巢。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-001-5', 'p0044', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '知人善察，難眩以偽，拔于禁、樂進於行陣之間，取張遼、徐晃於亡虜之內，皆佐命立功，列為名將；其餘拔出細微，登為牧守者，不可勝數。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-004-6', 'p0044', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '秋七月，詔祀故大司馬曹真、曹休、征南大將軍夏侯尚、太常桓階、司空陳羣、太傅鍾繇、車騎將軍張郃、左將軍徐晃、前將軍張遼、右將軍樂進、太尉華歆、司徒王朗、驃騎將軍曹洪、征西將軍夏侯淵、後將軍朱靈、文聘、執金吾臧霸、破虜將軍李典、立義將軍龐德、武猛校尉典韋於太祖廟庭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-009-7', 'p0044', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '帝征孫權，以休為征東大將軍，假黃鉞，督張遼等及諸州郡二十餘軍，擊權大將呂範等於洞浦，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-012-8', 'p0044', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '牟平賊從錢，衆亦數千，夔率郡兵與張遼共討定之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-015-9', 'p0044', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '又語張遼、樂進等曰：「揚州刺史曉達軍事，動靜與共咨議。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-015-10', 'p0044', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '一二日必有密書促卿進道，張遼等又將被召。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-017-11', 'p0044', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '張遼字文遠，鴈門馬邑人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-017-12', 'p0044', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '權甚憚焉，勑諸將：「張遼雖病，不可當也，慎之！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-017-13', 'p0044', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '建安十一年，太祖表漢帝，稱進及于禁、張遼曰：「武力旣弘，計略周備，質忠信一，守執節義，每臨戰攻，常為督率，奮彊突固，無堅不陷，自援枹鼓，手不知倦。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-017-14', 'p0044', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '太祖還，留進與張遼、李典屯合肥，增邑五百，并前凡千二百戶。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-017-15', 'p0044', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '後與臧霸等攻梅成，張遼、張郃等討陳蘭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-017-16', 'p0044', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '是時，禁與張遼、樂進、張郃、徐晃俱為名將，太祖每征伐，咸遞行為軍鋒，還為後拒；而禁持軍嚴整，得賊財物，無所私入，由是賞賜特重。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-017-17', 'p0044', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '從討柳城，與張遼俱為軍鋒，以功遷平狄將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-017-18', 'p0044', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '別征東萊，討管承，又與張遼討陳蘭、梅成等，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-017-19', 'p0044', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '或注記有遺漏，未如張遼、徐晃之備詳也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-018-20', 'p0044', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '與張遼、樂進屯合肥，孫權率衆圍之，遼欲奉教出戰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-018-21', 'p0044', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '張遼之討陳蘭，霸別遣至皖，討吳將韓當，使權不得救蘭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-018-22', 'p0044', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '霸從討孫權於濡須口，與張遼為前鋒，行遇霖雨，大軍先及，水遂長，賊舩稍進，將士皆不安。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-023-23', 'p0044', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '時于禁屯潁陰，樂進屯陽翟，張遼屯長社，諸將任氣，多共不協；使儼并參三軍，每事訓喻，遂相親睦。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-023-24', 'p0044', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '太祖征荊州，以儼領章陵太守，徙都督護軍，護于禁、張遼、張郃、朱靈、李典、路招、馮楷七軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-025-25', 'p0044', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '毗欲弘廣主意，當舉若張遼之疇，安有於一將之死而可以祖宗為譬哉？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-027-26', 'p0044', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '將軍張遼與其護軍武周有隙。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-028-27', 'p0044', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '文帝踐阼，拜散騎常侍，出為兖州刺史，與張遼等至廣陵討孫權。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-032-28', 'p0044', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '布由是遣中郎將高順、北地太守張遼等攻備。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-036-29', 'p0044', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '紹遣大將軍顏良攻東郡太守劉延於白馬，曹公使張遼及羽為先鋒擊之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-036-30', 'p0044', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '初，曹公壯羽為人，而察其心神無乆留之意，謂張遼曰：「卿試以情問之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-047-31', 'p0044', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '兵皆就路，權與凌統、甘寧等在津北為魏將張遼所襲，統等以死扞權，權乘駿馬越津橋得去。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-047-32', 'p0044', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '獻帝春秋曰：張遼問吳降人：「向有紫髯將軍，長上短下，便馬善射，是誰？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-047-33', 'p0044', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '秋九月，魏乃命曹休、張遼、臧霸出洞口，曹仁出濡須，曹真、夏侯尚、張郃、徐晃圍南郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-054-34', 'p0044', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '旣而張遼至夾石，聞城已拔，乃退。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-054-35', 'p0044', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '師還，遂征合肥，旣徹兵，為張遼等所襲，蒙與淩統以死扞衞。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-055-36', 'p0044', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '從征合肥，魏將張遼襲權於津北，欽力戰有功，遷盪寇將軍，領濡須督。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-055-37', 'p0044', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '權曰：「孟德有張遼，孤有興霸，足相敵也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-055-38', 'p0044', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '張遼覘望知之，即將步騎奄至。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-055-39', 'p0044', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '時權徹軍，前部已發，魏將張遼等奄至津北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-055-40', 'p0044', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '合肥之役，張遼奄至，諸將不備，陳武鬬死，宋謙、徐盛皆披走，璋身次在後，便馳進，橫馬斬謙、盛兵走者二人，兵皆還戰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-056-41', 'p0044', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '曹休、張遼、臧霸等來伐，範督徐盛、全琮、孫韶等，以舟師拒休等於洞口。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-060-42', 'p0044', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '江表傳曰：權征合肥還，為張遼所掩襲於津北，幾至危殆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0045-a04-001-0', 'p0045', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '遣樂進、李典擊之，幹還守壺關城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0045-a04-001-1', 'p0045', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '秋八月，公東征海賊管承，至淳于，遣樂進、李典擊破之，承走入海島。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0045-a04-001-2', 'p0045', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '知人善察，難眩以偽，拔于禁、樂進於行陣之間，取張遼、徐晃於亡虜之內，皆佐命立功，列為名將；其餘拔出細微，登為牧守者，不可勝數。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0045-a04-004-3', 'p0045', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '秋七月，詔祀故大司馬曹真、曹休、征南大將軍夏侯尚、太常桓階、司空陳羣、太傅鍾繇、車騎將軍張郃、左將軍徐晃、前將軍張遼、右將軍樂進、太尉華歆、司徒王朗、驃騎將軍曹洪、征西將軍夏侯淵、後將軍朱靈、文聘、執金吾臧霸、破虜將軍李典、立義將軍龐德、武猛校尉典韋於太祖廟庭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0045-a04-006-4', 'p0045', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '遣樂進、李典擊之，未拔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0045-a04-015-5', 'p0045', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '又語張遼、樂進等曰：「揚州刺史曉達軍事，動靜與共咨議。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0045-a04-017-6', 'p0045', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '太祖還許，使遼與樂進拔陰安，徙其民河南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0045-a04-017-7', 'p0045', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '太祖旣征孫權還，使遼與樂進、李典等將七千餘人屯合肥。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0045-a04-017-8', 'p0045', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '樂進字文謙，陽平衞國人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0045-a04-017-9', 'p0045', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '復與樂進等將步騎五千，擊紹別營，從延津西南緣河至汲、獲嘉二縣，焚燒保聚三十餘屯，斬首獲生各數千，降紹將何茂、王摩等二十餘人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0045-a04-017-10', 'p0045', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '是時，禁與張遼、樂進、張郃、徐晃俱為名將，太祖每征伐，咸遞行為軍鋒，還為後拒；而禁持軍嚴整，得賊財物，無所私入，由是賞賜特重。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0045-a04-017-11', 'p0045', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '張郃以巧變為稱，樂進以驍果顯名，而鑒其行事，未副所聞。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0045-a04-018-12', 'p0045', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '從圍鄴，鄴定，與樂進圍高幹於壺關，擊管承於長廣，皆破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0045-a04-018-13', 'p0045', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '與張遼、樂進屯合肥，孫權率衆圍之，遼欲奉教出戰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0045-a04-018-14', 'p0045', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '與樂進討關羽於尋口，有功，進封延壽亭侯，加討逆將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0045-a04-023-15', 'p0045', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '時于禁屯潁陰，樂進屯陽翟，張遼屯長社，諸將任氣，多共不協；使儼并參三軍，每事訓喻，遂相親睦。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0045-a04-032-16', 'p0045', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '孫氏與孤本為脣齒，又樂進在青泥與關羽相拒，今不往救羽，進必大克，轉侵州界，其憂有甚於魯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0045-a04-035-17', 'p0045', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '羽圍襄陽，將降曹仁，生獲于禁，當時北邊大小憂懼，孟德身出南陽，樂進、徐晃等為救，圍不即解，故蔣子通言彼時有徙許渡河之計，會國家襲取南郡，羽乃解軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0045-a04-047-18', 'p0045', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '備、瑜等復追至南郡，曹公遂北還，留曹仁、徐晃於江陵，使樂進守襄陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0045-a04-047-19', 'p0045', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '」遼及樂進相遇，言不早知之，急追自得，舉軍歎恨。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a03-076-0', 'p0046', 'houhanshu', 'a03-076', '《後漢書·卷七十六》', '數引公卿郎將，列于禁坐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a03-095-1', 'p0046', 'houhanshu', 'a03-095', '《二十四史-後漢書-志第五‧禮儀中》', '中黃門行之，宂從僕射將之，以逐惡鬼于禁中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a04-001-2', 'p0046', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '」秋八月，公進軍黎陽，使臧霸等入青州破齊、北海、東安，留于禁屯河上。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a04-001-3', 'p0046', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '知人善察，難眩以偽，拔于禁、樂進於行陣之間，取張遼、徐晃於亡虜之內，皆佐命立功，列為名將；其餘拔出細微，登為牧守者，不可勝數。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a04-002-4', 'p0046', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '秋八月，孫權遣使奉章，并遣于禁等還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a04-004-5', 'p0046', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '衮後為于禁司馬，見魏略游說傳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a04-009-6', 'p0046', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '昌狶反，遣于禁擊之，未拔，復遣淵與禁并力，遂擊狶，降其十餘屯，狶詣禁降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a04-009-7', 'p0046', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '關羽攻樊，時漢水暴溢，于禁等七軍皆沒，禁降羽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a04-013-8', 'p0046', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '」肅曰：「昔關羽率荊州之衆，降于禁於漢濵，遂有北向爭天下之志。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a04-014-9', 'p0046', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '」民有誣告濟為謀叛主率者，太祖聞之，指前令與左將軍于禁、沛相封仁等曰：「蔣濟寧有此事！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a04-014-10', 'p0046', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '司馬宣王及濟說太祖曰：「于禁等為水所沒，非戰攻之失，於國家大計未足有損。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a04-017-11', 'p0046', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '陳蘭、梅成以氐六縣叛，太祖遣于禁、臧霸等討成，遼督張郃、牛蓋等討蘭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a04-017-12', 'p0046', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '建安十一年，太祖表漢帝，稱進及于禁、張遼曰：「武力旣弘，計略周備，質忠信一，守執節義，每臨戰攻，常為督率，奮彊突固，無堅不陷，自援枹鼓，手不知倦。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a04-017-13', 'p0046', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '于禁字文則，泰山鉅平人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a04-017-14', 'p0046', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '會漢水暴隘，于禁等沒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a04-017-15', 'p0046', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '于禁最號毅重，然弗克其終。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a04-018-16', 'p0046', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '」惇不聽，與于禁追之，典留守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a04-018-17', 'p0046', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '又與于禁討昌豨，與夏侯淵討黃巾餘賊徐和等，有功，遷徐州刺史。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a04-022-18', 'p0046', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '時大將軍入于禁中，泰見之悲慟，大將軍亦對之泣，謂曰：「玄伯，其如我何？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a04-023-19', 'p0046', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '時于禁屯潁陰，樂進屯陽翟，張遼屯長社，諸將任氣，多共不協；使儼并參三軍，每事訓喻，遂相親睦。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a04-023-20', 'p0046', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '太祖征荊州，以儼領章陵太守，徙都督護軍，護于禁、張遼、張郃、朱靈、李典、路招、馮楷七軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a04-026-21', 'p0046', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '關羽圍襄陽，寵助征南將軍曹仁屯樊城拒之，而左將軍于禁等軍以霖雨水長為羽所沒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a04-032-22', 'p0046', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '使拒夏侯惇、于禁等於博望。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a04-032-23', 'p0046', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '時關羽攻曹公將曹仁，禽于禁於樊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a04-035-24', 'p0046', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '羽圍襄陽，將降曹仁，生獲于禁，當時北邊大小憂懼，孟德身出南陽，樂進、徐晃等為救，圍不即解，故蔣子通言彼時有徙許渡河之計，會國家襲取南郡，羽乃解軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a04-036-25', 'p0046', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '羽忿其淹遲，又自已得于禁等，乃罵曰：「狢子敢爾，如使樊城拔，吾不能滅汝邪！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a04-047-26', 'p0046', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '二十四年，關羽圍曹仁於襄陽，曹公遣左將軍于禁救之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a04-047-27', 'p0046', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '蒙據江陵，撫其老弱，釋于禁之囚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a04-047-28', 'p0046', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '」自魏文帝踐阼，權使命稱藩，及遣于禁等還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a04-047-29', 'p0046', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '」帝問其狀，咨曰：「納魯肅於凡品，是其聦也；拔呂蒙於行陣，是其明也；獲于禁而不害，是其仁也；取荊州而兵不血刃，是其智也；據三州虎視於天下，是其雄也；屈身於陛下，是其略也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a04-047-30', 'p0046', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '先帝知權姦以求用，時以于禁敗於水災，等當討羽，因以委權。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a04-047-31', 'p0046', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '後領護于禁軍，軍沒，為關羽所得。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a04-047-32', 'p0046', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '」初東里衮為于禁軍司馬，前與周俱沒，又俱還到，有詔皆見之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a04-054-33', 'p0046', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '魏使于禁救樊，羽盡禽禁等，人馬數萬，託以糧乏，擅取湘關米。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a04-057-34', 'p0046', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '魏將于禁為羽所獲，繫在城中，權至釋之，請與相見。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a04-058-35', 'p0046', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '」又曰：「于禁等見獲，遐邇欣歎，以為將軍之勳足以長世，雖昔晉文城濮之師，淮陰拔趙之略，蔑以尚茲。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a05-001-36', 'p0046', 'jinshu', 'a05-001', '《晉書·卷一》', '及蜀將關羽圍曹仁於樊，于禁等七軍皆沒，脩、方果降羽，而仁圍甚急焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a05-037-37', 'p0046', 'jinshu', 'a05-037', '《晉書-卷三十七・列傳第七》', '時孫權稱藩，請送任子，當遣前將軍于禁還，久而不至。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a05-037-38', 'p0046', 'jinshu', 'a05-037', '《晉書-卷三十七・列傳第七》', '權雖未送任子，于禁不至，猶宜以寬待之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a03-074-0', 'p0047', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '」乃使高覽、張郃等攻操營，不下。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a03-074-1', 'p0047', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '魏志曰：「張郃字儁文，河閒鄚人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-001-2', 'p0047', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '」乃使張郃、高覽攻曹洪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-001-3', 'p0047', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '張郃等見事急，共引公入船。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-001-4', 'p0047', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '三月，公西征張魯，至陳倉，將自武都入氐；氐人塞道，先遣張郃、朱靈等攻破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-001-5', 'p0047', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '劉備襲劉璋，取益州，遂據巴中；遣張郃擊之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-002-6', 'p0047', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '中軍、征南攻圍江陵，左將軍張郃等舳艫直渡，擊其南渚，賊赴水溺死者數千人，又為地道攻城，城中外雀鼠不得出入，此几上肉耳！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-003-7', 'p0047', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '右將軍張郃擊亮於街亭，大破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-004-8', 'p0047', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '秋七月，詔祀故大司馬曹真、曹休、征南大將軍夏侯尚、太常桓階、司空陳羣、太傅鍾繇、車騎將軍張郃、左將軍徐晃、前將軍張遼、右將軍樂進、太尉華歆、司徒王朗、驃騎將軍曹洪、征西將軍夏侯淵、後將軍朱靈、文聘、執金吾臧霸、破虜將軍李典、立義將軍龐德、武猛校尉典韋於太祖廟庭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-006-9', 'p0047', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '太祖還，未至營，紹將高覽、張郃等率其衆降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-009-10', 'p0047', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '」遂行，使張郃督步騎五千在前，從陳倉狹道入，淵自督糧在後。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-009-11', 'p0047', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '淵別遣張郃等平河關，渡河入小湟中，河西諸羌盡降，隴右平。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-009-12', 'p0047', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '會魯降，漢中平，以淵行都護將軍，督張郃、徐晃等平巴郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-009-13', 'p0047', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '淵使張郃護東圍，自將輕兵護南圍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-009-14', 'p0047', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '帝遣真督諸軍軍郿，遣張郃擊亮將馬謖，大破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-010-15', 'p0047', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '紹將張郃、高覽燒攻櫓降，紹遂棄軍走。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-017-16', 'p0047', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '陳蘭、梅成以氐六縣叛，太祖遣于禁、臧霸等討成，遼督張郃、牛蓋等討蘭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-017-17', 'p0047', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '後與臧霸等攻梅成，張遼、張郃等討陳蘭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-017-18', 'p0047', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '是時，禁與張遼、樂進、張郃、徐晃俱為名將，太祖每征伐，咸遞行為軍鋒，還為後拒；而禁持軍嚴整，得賊財物，無所私入，由是賞賜特重。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-017-19', 'p0047', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '張郃字儁乂，河閒鄚人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-017-20', 'p0047', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '臣松之案武紀及袁紹傳並云袁紹使張郃、高覽攻太祖營，郃等聞淳于瓊破，遂來降，紹衆於是大潰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-017-21', 'p0047', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '張郃以巧變為稱，樂進以驍果顯名，而鑒其行事，未副所聞。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-023-22', 'p0047', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '襲與張郃、郭淮糾攝諸軍事，權宜以郃為督，以一衆心，三軍遂定。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-023-23', 'p0047', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '太祖征荊州，以儼領章陵太守，徙都督護軍，護于禁、張遼、張郃、朱靈、李典、路招、馮楷七軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-025-24', 'p0047', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '張郃追之，為流矢所中死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-025-25', 'p0047', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '今國內所少，豈張郃乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-026-26', 'p0047', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '淵遇害，軍中擾擾，淮收散卒，推盪寇將軍張郃為軍主，諸營乃定。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-026-27', 'p0047', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '又行征羌護軍，護左將軍張郃、冠軍將軍楊秋討山賊鄭甘、盧水叛胡，皆破平之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-026-28', 'p0047', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '張郃擊謖，淮攻詳營，皆破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-032-29', 'p0047', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '曹公使夏侯淵、張郃屯漢中，數數犯暴巴界。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-033-30', 'p0047', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '八年秋，魏使司馬懿由西城，張郃由子午，曹真由斜谷，斜，余奢反。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-033-31', 'p0047', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '魏司馬懿、張郃救祁山。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-035-32', 'p0047', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '及至孟德，以其譎勝之力，舉數十萬之師，救張郃於陽平，勢窮慮悔，僅能自脫，辱其鋒銳之衆，遂喪漢中之地，深知神器不可妄獲，旋還未至，感毒而死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-035-33', 'p0047', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '魏明帝西鎮長安，命張郃拒亮，亮使馬謖督諸軍在前，與郃戰于街亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-035-34', 'p0047', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '」乃使西屯長安，督張郃、費曜、戴陵、郭淮等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-035-35', 'p0047', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '張郃曰：「彼遠來逆我，請戰不得，謂我利在不戰，欲以長計制之也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-035-36', 'p0047', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '五月辛巳，乃使張郃攻无當監何平於南圍，自案中道向亮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-035-37', 'p0047', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '糧盡退軍，與魏將張郃交戰，射殺郃。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-035-38', 'p0047', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '郭沖五事曰：魏明帝自征蜀，幸長安，遣宣王督張郃諸軍，雍、涼勁卒三十餘萬，潛軍密進，規向劒閣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-035-39', 'p0047', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '」臨戰之日，莫不拔刃爭先，以一當十，殺張郃，却宣王，一戰大剋，此信之由也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-036-40', 'p0047', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '曹公破張魯，留夏侯淵、張郃守漢川。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-037-41', 'p0047', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '二十二年，正說先主曰：「曹操一舉而降張魯，定漢中，不因此勢以圖巴、蜀，而留夏侯淵、張郃屯守，身遽北還，此非其智不逮而力不足也，必將內有憂偪故耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-039-42', 'p0047', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '建興六年，亮出軍向祁山，時有宿將魏延、吳壹等，論者皆言以為宜令為先鋒，而亮違衆拔謖，統大衆在前，與魏將張郃戰于街亭，為郃所破，士卒離散。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-040-43', 'p0047', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '旣亡漢中，使夏侯淵、張郃深入于巴，幾喪一州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-043-44', 'p0047', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '衆盡星散，惟平所領千人，鳴鼓自持，魏將張郃疑其伏兵，不往偪也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-043-45', 'p0047', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '魏大將軍司馬宣王攻亮，張郃攻平，平堅守不動，郃不能克。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-044-46', 'p0047', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '未及遣迎兾中人，會亮前鋒為張郃、費繇等所破，遂將維等却縮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-047-47', 'p0047', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '秋九月，魏乃命曹休、張遼、臧霸出洞口，曹仁出濡須，曹真、夏侯尚、張郃、徐晃圍南郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-056-48', 'p0047', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '魏遣曹真、夏侯尚、張郃等攻江陵，魏文帝自住宛，為其勢援，連屯圍城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a05-001-49', 'p0047', 'jinshu', 'a05-001', '《晉書·卷一》', '」乃使帝西屯長安，都督雍、梁二州諸軍事，統車騎將軍張郃、後將軍費曜、征蜀護軍戴淩、雍州刺史郭淮等討亮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a05-001-50', 'p0047', 'jinshu', 'a05-001', '《晉書·卷一》', '張郃勸帝分軍住雍、郿為後鎮，帝曰：「料前軍獨能當之者，將軍言是也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a05-013-51', 'p0047', 'jinshu', 'a05-013', '《晉書·卷十三》', '」其七月，車騎將軍張郃追諸葛亮，為亮所害。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0048-a04-001-0', 'p0048', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '紹若有十倍之衆，理應當悉力圍守，使出入斷絕，而公使徐晃等擊其運車，公又自出擊淳于瓊等，揚旌往還，曾無抵閡，明紹力不能制，是不得甚少，二也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0048-a04-001-1', 'p0048', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '袁紹運穀車數千乘至，公用荀攸計，遣徐晃、史渙邀擊，大破之，盡燒其車。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0048-a04-001-2', 'p0048', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '太原商曜等以大陵叛，遣夏侯淵、徐晃圍破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0048-a04-001-3', 'p0048', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '公急持之，而潛遣徐晃、朱靈等夜渡蒲阪津，據河西為營。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0048-a04-001-4', 'p0048', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '知人善察，難眩以偽，拔于禁、樂進於行陣之間，取張遼、徐晃於亡虜之內，皆佐命立功，列為名將；其餘拔出細微，登為牧守者，不可勝數。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0048-a04-004-5', 'p0048', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '秋七月，詔祀故大司馬曹真、曹休、征南大將軍夏侯尚、太常桓階、司空陳羣、太傅鍾繇、車騎將軍張郃、左將軍徐晃、前將軍張遼、右將軍樂進、太尉華歆、司徒王朗、驃騎將軍曹洪、征西將軍夏侯淵、後將軍朱靈、文聘、執金吾臧霸、破虜將軍李典、立義將軍龐德、武猛校尉典韋於太祖廟庭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0048-a04-009-6', 'p0048', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '太祖征孫權還，使淵督諸將擊廬江叛者雷緒，緒破，又行征西護軍，督徐晃擊太原賊，攻下二十餘屯，斬賊帥商曜，屠其城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0048-a04-009-7', 'p0048', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '會魯降，漢中平，以淵行都護將軍，督張郃、徐晃等平巴郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0048-a04-009-8', 'p0048', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '徐晃救至，水亦稍減，晃從外擊羽，仁得潰圍出，羽退走。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0048-a04-009-9', 'p0048', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '仁與徐晃攻破邵，遂入襄陽，使將軍高遷等徙漢南附化民於漢北，文帝遣使即拜仁大將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0048-a04-009-10', 'p0048', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '以真為征蜀護軍，督徐晃等破劉備別將高詳於陽平。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0048-a04-014-11', 'p0048', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '」即勑救將徐晃以權書射著圍裏及羽屯中，圍裏聞之，志氣百倍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0048-a04-017-12', 'p0048', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '遼未至，徐晃已破關羽，仁圍解。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0048-a04-017-13', 'p0048', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '是時，禁與張遼、樂進、張郃、徐晃俱為名將，太祖每征伐，咸遞行為軍鋒，還為後拒；而禁持軍嚴整，得賊財物，無所私入，由是賞賜特重。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0048-a04-017-14', 'p0048', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '徐晃字公明，河東楊人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0048-a04-017-15', 'p0048', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '或注記有遺漏，未如張遼、徐晃之備詳也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0048-a04-022-16', 'p0048', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '曹仁為關羽所圍，太祖遣徐晃救之，不解。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0048-a04-023-17', 'p0048', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '儼以議郎參仁軍事南行，與平寇將軍徐晃俱前。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0048-a04-026-18', 'p0048', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '會徐晃等救至，寵力戰有功，羽遂退。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0048-a04-035-19', 'p0048', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '羽圍襄陽，將降曹仁，生獲于禁，當時北邊大小憂懼，孟德身出南陽，樂進、徐晃等為救，圍不即解，故蔣子通言彼時有徙許渡河之計，會國家襲取南郡，羽乃解軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0048-a04-036-20', 'p0048', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '而曹公遣徐晃救曹仁，蜀記曰：羽與晃宿相愛，遙共語，但說平生，不及軍事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0048-a04-040-21', 'p0048', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '遣征南將軍夏侯尚、右將軍徐晃與達共襲封。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0048-a04-047-22', 'p0048', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '備、瑜等復追至南郡，曹公遂北還，留曹仁、徐晃於江陵，使樂進守襄陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0048-a04-047-23', 'p0048', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '秋九月，魏乃命曹休、張遼、臧霸出洞口，曹仁出濡須，曹真、夏侯尚、張郃、徐晃圍南郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0048-a04-058-24', 'p0048', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '聞徐晃等步騎駐旌，闚望麾葆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0049-a04-001-0', 'p0049', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '遣樂進、李典擊之，幹還守壺關城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0049-a04-001-1', 'p0049', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '秋八月，公東征海賊管承，至淳于，遣樂進、李典擊破之，承走入海島。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0049-a04-001-2', 'p0049', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '八月，孫權圍合肥，張遼、李典擊破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0049-a04-004-3', 'p0049', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '秋七月，詔祀故大司馬曹真、曹休、征南大將軍夏侯尚、太常桓階、司空陳羣、太傅鍾繇、車騎將軍張郃、左將軍徐晃、前將軍張遼、右將軍樂進、太尉華歆、司徒王朗、驃騎將軍曹洪、征西將軍夏侯淵、後將軍朱靈、文聘、執金吾臧霸、破虜將軍李典、立義將軍龐德、武猛校尉典韋於太祖廟庭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0049-a04-006-4', 'p0049', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '遣樂進、李典擊之，未拔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0049-a04-017-5', 'p0049', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '太祖旣征孫權還，使遼與樂進、李典等將七千餘人屯合肥。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0049-a04-017-6', 'p0049', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '太祖征管承，軍淳于，遣進與李典擊之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0049-a04-017-7', 'p0049', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '太祖還，留進與張遼、李典屯合肥，增邑五百，并前凡千二百戶。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0049-a04-018-8', 'p0049', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '李典字曼成，山陽鉅野人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0049-a04-018-9', 'p0049', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '評曰：李典貴尚儒雅，義忘私隙，美矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0049-a04-023-10', 'p0049', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '太祖征荊州，以儼領章陵太守，徙都督護軍，護于禁、張遼、張郃、朱靈、李典、路招、馮楷七軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0050-a03-001-0', 'p0050', 'houhanshu', 'a03-001', '《後漢書·卷一上》', '宛人李通等以圖讖說光武云：「劉氏復起，李氏為輔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0050-a03-001-1', 'p0050', 'houhanshu', 'a03-001', '《後漢書·卷一上》', '十月，與李通從弟軼等起於宛，時年二十八。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0050-a03-011-2', 'p0050', 'houhanshu', 'a03-011', '《後漢書·卷十一》', '更始乃先封宗室太常將軍劉祉為定陶王，劉賜為宛王，劉慶為燕王，劉歙為元氏王，大將軍劉嘉為漢中王，劉信為汝陰王；後遂立王匡為比陽王，王鳳為宜城王，朱鮪為膠東王，衞尉大將軍張卬為淮陽王，廷尉大將軍王常為鄧王，執金吾大將軍廖湛為穰王，申屠建為平氏王，尚書胡殷為隨王，柱天大將軍李通為西平王，西平，縣，屬汝南郡，故城在今豫州郾城縣南也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0050-a03-011-3', 'p0050', 'houhanshu', 'a03-011', '《後漢書·卷十一》', '乃徙鮪為左大司馬，劉賜為前大司馬，使與李軼、李通、王常等鎮撫關東。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0050-a03-014-4', 'p0050', 'houhanshu', 'a03-014', '《後漢書·卷十四》', '於是分遣親客，使鄧晨起新野，光武與李通、李軼起於宛。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0050-a03-015-5', 'p0050', 'houhanshu', 'a03-015', '《後漢書·卷十五》', '李通　王常　鄧晨　來歙　歷伯珍');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0050-a03-015-6', 'p0050', 'houhanshu', 'a03-015', '《後漢書·卷十五》', '李通字次元，南陽宛人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0050-a03-015-7', 'p0050', 'houhanshu', 'a03-015', '《後漢書·卷十五》', '續漢書曰：「先是李通同母弟申徒臣能為醫，難使，伯升殺之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0050-a03-015-8', 'p0050', 'houhanshu', 'a03-015', '《後漢書·卷十五》', '李通豈知夫所欲而未識以道者乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0050-a03-015-9', 'p0050', 'houhanshu', 'a03-015', '《後漢書·卷十五》', '伯升聞下江軍在宜秋，即與光武及李通俱造常壁，曰：「願見下江一賢將，議大事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0050-a03-015-10', 'p0050', 'houhanshu', 'a03-015', '《後漢書·卷十五》', '鄧晨代以吏二千石為豪，李通家富為贍也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0050-a03-017-11', 'p0050', 'houhanshu', 'a03-017', '《後漢書·卷十七》', '是時列侯唯高密、固始、膠東三侯與公卿參議國家大事，高密侯鄧禹，固始侯李通。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0050-a03-021-12', 'p0050', 'houhanshu', 'a03-021', '《後漢書·卷二十一》', '八年，東郡、濟陰盜賊羣起，遣大司空李通、橫野大將軍王常擊之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0050-a03-022-13', 'p0050', 'houhanshu', 'a03-022', '《後漢書·卷二十二》', '明年，大司空李通罷，以成行大司空事，居府如真，數月復拜揚武將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0050-a03-022-14', 'p0050', 'houhanshu', 'a03-022', '《後漢書·卷二十二》', '永平中，顯宗追感前世功臣，乃圖畫二十八將於南宮雲臺，其外又有王常、李通、竇融、卓茂，合三十二人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0050-a03-022-15', 'p0050', 'houhanshu', 'a03-022', '《後漢書·卷二十二》', '太傅高密侯鄧禹　                   中山太守全椒侯馬成                   大司馬廣平侯吳漢                   河南尹阜成侯王梁                   左將軍膠東侯賈復                   琅邪太守祝阿侯陳俊                   建威大將軍好畤侯耿弇                   驃騎大將軍參蘧侯杜茂                   執金吾雍奴侯寇恂                   積弩將軍昆陽侯傅俊                   征南大將軍舞陽侯岑彭                   左曹合肥侯堅鐔                   征西大將軍陽夏侯馮異                   上谷太守淮陽侯王霸                   建義大將軍鬲侯朱祐                   信都太守阿陵侯任光                   征虜將軍潁陽侯祭遵                   豫章太守中水侯李忠                   驃騎大將軍櫟陽侯景丹                   右將軍槐里侯萬脩                   虎牙大將軍安平侯蓋延                   太常靈壽侯邳彤                   衞尉安成侯銚期                   驍騎將軍昌成侯劉植                   東郡太守東光侯耿純                   橫野大將軍山桑侯王常                   城門校尉朗陵侯臧宮                   大司空固始侯李通                   捕虜將軍楊虛侯馬武                   大司空安豐侯竇融                   驃騎將軍慎侯劉隆                   太傅宣德侯卓茂');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0050-a03-036-16', 'p0050', 'houhanshu', 'a03-036', '《後漢書·卷三十六》', '元以才高著名，辟司空李通府。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0050-a03-036-17', 'p0050', 'houhanshu', 'a03-036', '《後漢書·卷三十六》', '李通罷，元後復辟司徒歐陽歙府，數陳當世便事、郊廟之禮，帝不能用。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0050-a03-070-18', 'p0050', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '若要離焚妻子以徇吳，李通誅宗族以從漢之類也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0050-a04-018-19', 'p0050', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '李通字文達，江夏平春人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0050-a04-018-20', 'p0050', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '昔樂羊食子，李通覆家，經國之臣，寧懷妻孥邪？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0050-a04-018-21', 'p0050', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '李通、臧霸、文聘、呂虔鎮衞州郡，並著威惠。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0050-a04-023-22', 'p0050', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '惟陽安郡不動，而都尉李通急錄戶調。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0050-a04-023-23', 'p0050', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '儼與領陽安太守李通同治，通亦欲遣使。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0050-a04-042-24', 'p0050', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '益部耆舊傳曰：益州刺史董榮圖畫周像於州學，命從事李通頌之曰：「抑抑譙侯，好古述儒，寶道懷真，鑒世盈虛，雅名美迹，終始是書。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0051-a03-075-0', 'p0051', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '時太山臧霸等攻破莒城，許布財幣以相結，而未及送，布乃自往求之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0051-a04-001-1', 'p0051', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '太山臧霸、孫觀、吳敦、尹禮、昌狶各聚衆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0051-a04-001-2', 'p0051', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '」秋八月，公進軍黎陽，使臧霸等入青州破齊、北海、東安，留于禁屯河上。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0051-a04-003-3', 'p0051', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '魏書曰：行過繁昌，使執金吾臧霸行太尉事，以特牛祠受禪壇。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0051-a04-004-4', 'p0051', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '秋七月，詔祀故大司馬曹真、曹休、征南大將軍夏侯尚、太常桓階、司空陳羣、太傅鍾繇、車騎將軍張郃、左將軍徐晃、前將軍張遼、右將軍樂進、太尉華歆、司徒王朗、驃騎將軍曹洪、征西將軍夏侯淵、後將軍朱靈、文聘、執金吾臧霸、破虜將軍李典、立義將軍龐德、武猛校尉典韋於太祖廟庭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0051-a04-007-5', 'p0051', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '建尋為臧霸所襲破，得建資實。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0051-a04-010-6', 'p0051', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '」比行，布以敗劉備，而臧霸等應之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0051-a04-014-7', 'p0051', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '臧霸等旣富且貴，無復他望，但欲終其天年，保守祿祚而已，何肯乘危自投死地，以求徼倖？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0051-a04-015-8', 'p0051', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '建安二十二年，與夏侯惇、臧霸等征吳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0051-a04-017-9', 'p0051', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '陳蘭、梅成以氐六縣叛，太祖遣于禁、臧霸等討成，遼督張郃、牛蓋等討蘭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0051-a04-017-10', 'p0051', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '後與臧霸等攻梅成，張遼、張郃等討陳蘭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0051-a04-018-11', 'p0051', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '臧霸字宣高，泰山華人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0051-a04-018-12', 'p0051', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '與臧霸俱起，討黃巾，拜騎都尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0051-a04-018-13', 'p0051', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '臧霸少有孝烈之稱，文聘著垂泣之誠，是以魏武一面，委之以二方之任，豈直壯武見知於倉卒之間哉！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0051-a04-018-14', 'p0051', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '李通、臧霸、文聘、呂虔鎮衞州郡，並著威惠。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0051-a04-047-15', 'p0051', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '秋九月，魏乃命曹休、張遼、臧霸出洞口，曹仁出濡須，曹真、夏侯尚、張郃、徐晃圍南郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0051-a04-047-16', 'p0051', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '曹休使臧霸以輕船五百、敢死萬人襲攻徐陵，燒攻城車，殺略數千人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0051-a04-056-17', 'p0051', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '曹休、張遼、臧霸等來伐，範督徐盛、全琮、孫韶等，以舟師拒休等於洞口。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0051-a05-019-18', 'p0051', 'jinshu', 'a05-019', '《晉書·卷十九》', '四年八月，天子東巡，過繁昌，使執金吾臧霸行太尉事，以特牛祠受禪壇。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0052-a04-001-0', 'p0052', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '乃論荊州服從之功，侯者十五人，以劉表大將文聘為江夏太守，使統本兵，引用荊州名士韓嵩、鄧義等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0052-a04-003-1', 'p0052', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '八月，孫權攻江夏郡，太守文聘堅守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0052-a04-004-2', 'p0052', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '秋七月，詔祀故大司馬曹真、曹休、征南大將軍夏侯尚、太常桓階、司空陳羣、太傅鍾繇、車騎將軍張郃、左將軍徐晃、前將軍張遼、右將軍樂進、太尉華歆、司徒王朗、驃騎將軍曹洪、征西將軍夏侯淵、後將軍朱靈、文聘、執金吾臧霸、破虜將軍李典、立義將軍龐德、武猛校尉典韋於太祖廟庭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0052-a04-011-3', 'p0052', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '魏略純固傳以脂習、王脩、龐淯、文聘、成公英、郭憲、單固七人為一傳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0052-a04-018-4', 'p0052', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '文聘字仲業，南陽宛人也，為劉表大將，使禦北方。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0052-a04-018-5', 'p0052', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '臧霸少有孝烈之稱，文聘著垂泣之誠，是以魏武一面，委之以二方之任，豈直壯武見知於倉卒之間哉！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0052-a04-018-6', 'p0052', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '李通、臧霸、文聘、呂虔鎮衞州郡，並著威惠。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0052-a04-058-7', 'p0052', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '兼領兵馬，頗作邊害，而與北舊將文聘子休宿不協。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0053-a04-004-0', 'p0053', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '徐佗謀逆而許褚心動，忠誠之至遠同於日磾，且潼關之危，非褚不濟，褚之功烈有過典韋，今祀韋而不及褚，文所未達也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0053-a04-008-1', 'p0053', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '武皇帝意沮，便欲拔軍截山而還，遣故大將軍夏侯惇、將軍許褚呼山上兵還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0053-a04-018-2', 'p0053', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '許褚字仲康，譙國譙人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0053-a04-018-3', 'p0053', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '許褚、典韋折衝左右，抑亦漢之樊噲也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0053-a04-028-4', 'p0053', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '儀者，許褚之子，有功王室，猶不原貸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0053-a04-036-5', 'p0053', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '曹公與遂、超單馬會語，超負其多力，陰欲突前捉曹公，曹公左右將許褚瞋目眄之，超乃不敢動。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0054-a04-004-0', 'p0054', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '秋七月，詔祀故大司馬曹真、曹休、征南大將軍夏侯尚、太常桓階、司空陳羣、太傅鍾繇、車騎將軍張郃、左將軍徐晃、前將軍張遼、右將軍樂進、太尉華歆、司徒王朗、驃騎將軍曹洪、征西將軍夏侯淵、後將軍朱靈、文聘、執金吾臧霸、破虜將軍李典、立義將軍龐德、武猛校尉典韋於太祖廟庭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0054-a04-004-1', 'p0054', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '徐佗謀逆而許褚心動，忠誠之至遠同於日磾，且潼關之危，非褚不濟，褚之功烈有過典韋，今祀韋而不及褚，文所未達也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0054-a04-018-2', 'p0054', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '許褚、典韋折衝左右，抑亦漢之樊噲也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0055-a04-004-0', 'p0055', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '秋七月，詔祀故大司馬曹真、曹休、征南大將軍夏侯尚、太常桓階、司空陳羣、太傅鍾繇、車騎將軍張郃、左將軍徐晃、前將軍張遼、右將軍樂進、太尉華歆、司徒王朗、驃騎將軍曹洪、征西將軍夏侯淵、後將軍朱靈、文聘、執金吾臧霸、破虜將軍李典、立義將軍龐德、武猛校尉典韋於太祖廟庭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0055-a04-036-1', 'p0055', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '禁降羽，羽又斬將軍龐德。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0055-a04-036-2', 'p0055', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '蜀記曰：龐德子會，隨鍾、鄧伐蜀，蜀破，盡滅關氏家。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0055-a04-036-3', 'p0055', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '騰遣超隨繇討郭援、高幹於平陽，超將龐德親斬援首。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0055-a04-037-4', 'p0055', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '襄陽記曰：諸葛孔明為卧龍，龐士元為鳳雛，司馬德操為水鏡，皆龐德公語也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0056-a04-003-0', 'p0056', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '六月，征東將軍滿寵進軍拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0056-a04-004-1', 'p0056', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '」三月，以征東將軍滿寵為太尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0056-a04-014-2', 'p0056', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '邊候得權書，放乃改易其辭，往往換其本文而傅合之，與征東將軍滿寵，若欲歸化，封以示亮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0056-a04-014-3', 'p0056', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '如征東將軍滿寵、涼州刺史徐邈，並有譖毀之者，資皆盛陳其素行，使卒無纖介。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0056-a04-015-4', 'p0056', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '太和二年，帝使逵督前將軍滿寵、東莞太守胡質等四軍，從西陽直向東關，曹休從皖，司馬宣王從江陵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0056-a04-017-5', 'p0056', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '又與滿寵討關羽於漢津，與曹仁擊周瑜於江陵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0056-a04-021-6', 'p0056', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '青龍中，吳圍合肥，時東方吏士皆分休，征東將軍滿寵表請中軍兵，并召休將士，須集擊之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0056-a04-026-7', 'p0056', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '滿寵字伯寧，山陽昌邑人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0056-a04-026-8', 'p0056', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '後孫權號十萬衆攻新城，征東將軍滿寵欲率諸軍救之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0056-a04-026-9', 'p0056', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '評曰：滿寵立志剛毅，勇而有謀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0056-a05-013-10', 'p0056', 'jinshu', 'a05-013', '《晉書·卷十三》', '」三年三月，太尉滿寵薨。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0057-a04-003-0', 'p0057', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '冬十月，殄夷將軍田豫帥衆討吴將周賀於成山，殺賀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0057-a04-014-1', 'p0057', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '司馬彪戰略曰：太和六年，明帝遣平州刺史田豫乘海渡，幽州刺史王雄陸道，并攻遼東。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0057-a04-014-2', 'p0057', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '魏氏春秋曰：烏丸校尉田豫帥西部鮮卑泄歸尼等出塞，討軻比能、智鬱築鞬，破之，還至馬邑故城，比能帥三萬騎圍豫。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0057-a04-014-3', 'p0057', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '鄉人司空掾田豫、梁相宗豔皆妬害之，而楊豐黨附豫等，專為資構造謗端，怨隙甚重。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0057-a04-014-4', 'p0057', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '及當顯位，而田豫老疾在家。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0057-a04-019-5', 'p0057', 'sanguozhi', 'a04-019', '《三國志·魏書十九》', '用田豫計，固守要隙，虜乃退散。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0057-a04-026-6', 'p0057', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '田豫字國讓，漁陽雍奴人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0057-a04-026-7', 'p0057', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '太和二年，護烏丸校尉田豫出塞，為軻比能所圍於故馬邑城，移招求救。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0057-a04-026-8', 'p0057', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '其治邊之稱，次於田豫，百姓追思之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0057-a04-026-9', 'p0057', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '田豫居身清白，規畧明練。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0057-a04-027-10', 'p0057', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '故司空徐邈、征東將軍胡質、衞尉田豫皆服職前朝，歷事四世，出統戎馬，入贊庶政，忠清在公，憂國忘私，不營產業，身沒之後，家無餘財，朕甚嘉之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0057-a04-028-11', 'p0057', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '烏丸校尉田豫討胡有功，小違節度，愚以法繩之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0057-a04-030-12', 'p0057', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '田豫有馬城之圍，畢軌有陘北之敗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0057-a04-030-13', 'p0057', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '文帝踐阼，田豫為烏丸校尉，持節并護鮮卑，屯昌平。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0057-a04-030-14', 'p0057', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '田豫和合，使不得相侵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0057-a04-047-15', 'p0057', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '秋九月，魏將田豫要擊，斬賀于成山。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0058-a04-003-0', 'p0058', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '雍州刺史郭淮遣廣魏太守王贇、南安太守游弈將兵討惇。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0058-a04-004-1', 'p0058', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '二年夏五月，以征西將軍郭淮為車騎將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0058-a04-004-2', 'p0058', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '」乃使郭淮、陳泰悉關中之衆，解狄道之圍；勑毌丘儉等案兵自守，以新城委吳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0058-a04-004-3', 'p0058', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '癸未，車騎將軍郭淮薨。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0058-a04-009-4', 'p0058', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '霸聞曹爽被誅而玄又徵，以為禍必轉相及，心旣內恐；又霸先與雍州刺史郭淮不和，而淮代玄為征西，霸尤不安，故遂奔蜀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0058-a04-011-5', 'p0058', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '車騎將軍郭淮以意氣呼之，問其所欲，亦不肯言。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0058-a04-017-6', 'p0058', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '淵司馬郭淮乃令衆曰：「張將軍，國家名將，劉備所憚；今日事急，非張將軍不能安也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0058-a04-022-7', 'p0058', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '嘉平初，代郭淮為雍州刺史，加奮威將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0058-a04-022-8', 'p0058', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '征西將軍郭淮與泰謀所以禦之，泰曰：「麴城雖固，去蜀險遠，當須運糧。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0058-a04-023-9', 'p0058', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '襲與張郃、郭淮糾攝諸軍事，權宜以郃為督，以一衆心，三軍遂定。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0058-a04-026-10', 'p0058', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '郭淮字伯濟，太原陽曲人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0058-a04-026-11', 'p0058', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '郭淮方策精詳，垂問秦、雍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0058-a04-028-12', 'p0058', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '欽與郭淮書曰：「大將軍昭伯與太傅俱受顧命，登牀把臂，託付天下，此遠近所知。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0058-a04-028-13', 'p0058', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '」時郭淮已卒，欽未知，故有此書。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0058-a04-028-14', 'p0058', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '前與毌丘儉、郭淮等俱舉義兵，當共討師，埽除凶孽，誠臣慺慺愚管所執。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0058-a04-028-15', 'p0058', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '嘉平元年，與征西將軍郭淮拒蜀偏將軍姜維。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0058-a04-033-16', 'p0058', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '是歲，魏延破魏雍州刺史郭淮于陽谿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0058-a04-035-17', 'p0058', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '魏雍州刺史郭淮率衆欲擊戒，亮自出至建威，淮退還，遂平二郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0058-a04-035-18', 'p0058', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '前年耀師，馘斬王雙；今歲爰征，郭淮遁走；降集氐、羌，興復二郡，威鎮凶暴，功勳顯然。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0058-a04-035-19', 'p0058', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '」乃使西屯長安，督張郃、費曜、戴陵、郭淮等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0058-a04-035-20', 'p0058', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '郭淮、費曜等徼亮，亮破之，因大芟刈其麥，與宣王遇于上邽之東，斂兵依險，軍不得交，亮引而還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0058-a04-040-21', 'p0058', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '五年，諸葛亮駐漢中，更以延為督前部，領丞相司馬、涼州刺史，八年，使延西入羌中，魏後將軍費瑤、雍州刺史郭淮與延戰于陽谿，延大破淮等，遷為前軍師征西大將軍，假節，進封南鄭侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0058-a04-044-22', 'p0058', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '輙與費禕等議，以涼州胡塞之要，進退有資，賊之所惜；且羌、胡乃心思漢如渴，又昔偏軍入羌，郭淮破走，筭其長短，以為事首，宜以姜維為涼州刺史。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0058-a04-044-23', 'p0058', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '魏略曰：天水太守馬遵將維及諸官屬隨雍州刺史郭淮偶自西至洛門案行，會聞亮已到祁山，淮顧遵曰：「是欲不善！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0058-a04-044-24', 'p0058', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '又出隴西、南安、金城界，與魏大將軍郭淮、夏侯霸等戰於洮西。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0058-a05-001-25', 'p0058', 'jinshu', 'a05-001', '《晉書·卷一》', '」乃使帝西屯長安，都督雍、梁二州諸軍事，統車騎將軍張郃、後將軍費曜、征蜀護軍戴淩、雍州刺史郭淮等討亮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0058-a05-001-26', 'p0058', 'jinshu', 'a05-001', '《晉書·卷一》', '」遣將軍胡遵、雍州刺史郭淮共備陽遂，與亮會于積石。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0058-a05-002-27', 'p0058', 'jinshu', 'a05-002', '《晉書·卷二》', '蜀將姜維之寇隴右也，征西將軍郭淮自長安距之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0058-a05-013-28', 'p0058', 'jinshu', 'a05-013', '《晉書·卷十三》', '蜀將姜維攻隴西，車騎將軍郭淮討破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0059-a04-026-0', 'p0059', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '文帝初，北狄彊盛，侵擾邊塞，乃使豫持節護烏丸校尉，牽招、解儁并護鮮卑。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0059-a04-026-1', 'p0059', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '牽招字子經，安平觀津人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0059-a04-026-2', 'p0059', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '牽招秉義壯烈，威績顯著。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0060-a04-001-0', 'p0060', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '尚攻之急，譚遣辛毗乞降請救。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0060-a04-002-1', 'p0060', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '」　魏王侍中劉廙、辛毗、劉曄、尚書令桓階、尚書陳矯、陳羣、給事黃門侍郎王毖、董遇等言：「臣伏讀左中郎將李伏上事，考圖緯之言，以效神明之應，稽之古代，未有不然者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0060-a04-002-2', 'p0060', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '」於是侍中辛毗、劉曄、散騎常侍傅巽、衞臻、尚書令桓階、尚書陳矯、陳羣、給事中博士騎都尉蘇林、董巴等奏曰：「伏見太史丞許芝上魏國受命之符；令書懇切，允執謙讓，雖舜、禹、湯、文，義無以過。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0060-a04-003-3', 'p0060', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '宣王將出戰，辛毗杖節奉詔，勒宣王及軍吏已下，乃止。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0060-a04-006-4', 'p0060', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '尚攻之急，譚遣辛毗詣太祖請救。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0060-a04-006-5', 'p0060', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '初，譚之去，皆呼辛毗、郭圖家得出，而辛評家獨被收。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0060-a04-006-6', 'p0060', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '是時，辛毗在軍，聞門開，馳走詣獄，欲解其兄家，兄家已死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0060-a04-006-7', 'p0060', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '是日生縛配，將詣帳下，辛毗等逆以馬鞭擊其頭，罵之曰：「奴，汝今日真死矣！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0060-a04-006-8', 'p0060', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '配旣無撓辭，而辛毗等號哭不已，乃殺之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0060-a04-008-9', 'p0060', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '侍中辛毗、劉曄等在兵後，語惇、褚，言『官兵已據得賊要屯，賊已散走』。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0060-a04-010-10', 'p0060', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '前後所舉者，命世大才，邦邑則荀攸、鍾繇、陳羣，海內則司馬宣王，及引致當世知名郗慮、華歆、王朗、荀恱、杜襲、辛毗、趙儼之儔，終為卿相，以十數人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0060-a04-010-11', 'p0060', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '譚遣辛毗乞降請救，太祖將許之，以問羣下。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0060-a04-012-12', 'p0060', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '」太尉鍾繇、司徒華歆、鎮軍大將軍陳羣、侍中辛毗、尚書衞臻、守廷尉高柔等並表「勛父信有功於太祖」，求請勛罪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0060-a04-014-13', 'p0060', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '譚為尚軍所敗，走保平原，遣辛毗乞降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0060-a04-014-14', 'p0060', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '放、資旣善承順主上，又未嘗顯言得失，抑辛毗而助王思，以是獲譏於世。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0060-a04-016-15', 'p0060', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '每政有得失，常引綱維以正言，於是侍中辛毗等器重之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0060-a04-023-16', 'p0060', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '初，儼與同郡辛毗、陳羣、杜襲並知名，號曰辛、陳、杜、趙云。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0060-a04-024-17', 'p0060', 'sanguozhi', 'a04-024', '《三國志·魏書二十四》', '魏名臣奏載侍中辛毗奏曰：「昔桓階為尚書令，以崔林非尚書才，遷以為河間太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0060-a04-025-18', 'p0060', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '辛毗字佐治，潁川陽翟人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0060-a04-025-19', 'p0060', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '」宂從僕射畢軌表言：「尚書僕射王思精勤舊吏，忠亮計略不如辛毗，毗宜代思。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0060-a04-025-20', 'p0060', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '」陳羣曰：「亦誠如辛毗言。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0060-a04-025-21', 'p0060', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '評曰：辛毗、楊阜，剛亮公直，正諫匪躬，亞乎汲黯之高風焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0060-a04-035-22', 'p0060', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '使衞尉辛毗持節以制之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0060-a04-047-23', 'p0060', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '魏乃遣侍中辛毗、尚書桓階往與盟誓，并徵任子，權辭讓不受。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0060-a05-001-24', 'p0060', 'jinshu', 'a05-001', '《晉書·卷一》', '帝怒，表請決戰，天子不許，乃遣骨鯁臣衞尉辛毗杖節為軍師以制之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0060-a05-001-25', 'p0060', 'jinshu', 'a05-001', '《晉書·卷一》', '初，蜀將姜維聞毗來，謂亮曰：「辛毗杖節而至，賊不復出矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0061-a03-072-0', 'p0061', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '十九年，天水人楊阜破超，魏志曰：「阜字義山，天水兾人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0061-a04-003-1', 'p0061', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '百姓失農時，直臣楊阜、高堂隆等各數切諫，雖不能聽，常優容之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0061-a04-005-2', 'p0061', 'sanguozhi', 'a04-005', '《三國志·魏書五》', '陳羣雖抗言，楊阜引事比並，然皆不能極陳先王之禮，明封建繼嗣之義，忠至之辭，猶有闕乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0061-a04-015-3', 'p0061', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '旣臨二州十餘年，政惠著聞，其所禮辟扶風龐延、天水楊阜、安定胡遵、酒泉龐淯、燉煌張恭、周生烈等，終皆有名位。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0061-a04-022-4', 'p0061', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '袁子曰：或云「故少府楊阜豈非忠臣哉？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0061-a04-025-5', 'p0061', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '楊阜字義山，天水兾人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0061-a04-025-6', 'p0061', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '叙姑子楊阜，故為康從事，同等十餘人，皆略屬超，陰相結為康報仇，未有閒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0061-a04-025-7', 'p0061', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '及昂與楊阜等結謀討超，告異曰：「吾謀如是，事必萬全，當柰月何？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0061-a04-025-8', 'p0061', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '評曰：辛毗、楊阜，剛亮公直，正諫匪躬，亞乎汲黯之高風焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0061-a04-036-9', 'p0061', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '楊阜說曹公曰：「超有信、布之勇，甚得羌、胡心。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0061-a04-036-10', 'p0061', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '康故吏民楊阜、姜叙、梁寬、趙衢等合謀擊超。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0062-a04-004-0', 'p0062', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '八月丁卯，以太常高柔為司空。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0062-a04-004-1', 'p0062', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '四月，以司空高柔為司徒；光祿大夫徐邈為司空，固辭不受。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0062-a04-004-2', 'p0062', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '使兼太尉高柔奉策，用一元大武告于宗廟，遣芳歸藩于齊，以避皇位。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0062-a04-004-3', 'p0062', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '九月，以司徒高柔為太尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0062-a04-011-4', 'p0062', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '初，脩識高柔於弱冠，異王基於幼童，終皆遠至，世稱其知人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0062-a04-012-5', 'p0062', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '」太尉鍾繇、司徒華歆、鎮軍大將軍陳羣、侍中辛毗、尚書衞臻、守廷尉高柔等並表「勛父信有功於太祖」，求請勛罪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0062-a04-024-6', 'p0062', 'sanguozhi', 'a04-024', '《三國志·魏書二十四》', '高柔字文惠，陳留圉人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0062-a04-024-7', 'p0062', 'sanguozhi', 'a04-024', '《三國志·魏書二十四》', '評曰：韓曁處以靜居行化，出以任職流稱；崔林簡樸知能；高柔明於法理；孫禮剛斷伉厲；王觀清勁貞白：咸克致公輔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0062-a05-001-8', 'p0062', 'jinshu', 'a05-001', '《晉書·卷一》', '」於是假司徒高柔節，行大將軍事，領爽營，謂柔曰：「君為周勃矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0062-a05-002-9', 'p0062', 'jinshu', 'a05-002', '《晉書·卷二》', '二年秋八月甲寅，天子使太尉高柔授帝相國印綬，司空鄭沖致晉公茅土九錫，固辭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0062-a05-039-10', 'p0062', 'jinshu', 'a05-039', '《晉書-卷三十九・列傳第九》', '前渤海太守劉亮、從子北海太守搏、司空掾高柔並切諫，浚怒，誅之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0063-a04-004-0', 'p0063', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '庚子，以司隷校尉孫禮為司空。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0063-a04-010-1', 'p0063', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '」詡遂往，繡執子孫禮，煨果善視其家。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0063-a04-012-2', 'p0063', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '」涿郡孫禮、盧毓始入軍府，琰又名之曰：「孫疏亮亢烈，剛簡能斷，盧清警明理，百鍊不消，皆公才也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0063-a04-012-3', 'p0063', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '高密鄭玄，稱之鄭公，執子孫禮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0063-a04-016-4', 'p0063', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '畿為尚書僕射，二人各脩子孫禮見畿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0063-a04-022-5', 'p0063', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '寔之亡也，司空荀爽、太僕令韓融並制緦麻，執子孫禮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0063-a04-024-6', 'p0063', 'sanguozhi', 'a04-024', '《三國志·魏書二十四》', '孫禮字德達，涿郡容城人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0063-a04-024-7', 'p0063', 'sanguozhi', 'a04-024', '《三國志·魏書二十四》', '評曰：韓曁處以靜居行化，出以任職流稱；崔林簡樸知能；高柔明於法理；孫禮剛斷伉厲；王觀清勁貞白：咸克致公輔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0063-a04-027-8', 'p0063', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '邈同郡韓觀曼遊，有鑒識器幹，與邈齊名，而在孫禮、盧毓先，為豫州刺史，甚有治功，卒官。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0064-a04-001-0', 'p0064', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '於是中軍師王凌、謝亭侯荀攸、前軍師東武亭侯鍾繇、左軍師涼茂、右軍師毛玠、平虜將軍華鄉侯劉勳、建武將軍清苑亭侯劉若、伏波將軍高安侯夏侯惇、揚武將軍都亭侯王忠、奮威將軍樂鄉侯劉展、建忠將軍昌鄉亭侯鮮于輔、奮武將軍安國亭侯程昱、太中大夫都鄉侯賈詡、軍師祭酒千秋亭侯董昭、都亭侯薛洪、南鄉亭侯董蒙、關內侯王粲、傅巽、祭酒王選、袁奐、王朗、張承、任藩、杜襲、中護軍國明亭侯曹洪、中領軍萬歲亭侯韓浩、行驍騎將軍安平亭侯曹仁、領護軍將軍王圖、長史萬潛、謝奐、袁霸等勸進曰：「自古三代，胙臣以土，受命中興，封秩輔佐，皆所以襃功賞德，為國藩衞也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0064-a04-027-1', 'p0064', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '是時青土初定，刺史王凌特表請基為別駕，後召為秘書郎，凌復請還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a03-085-0', 'p0065', 'houhanshu', 'a03-085', '《後漢書·卷八十五》', '魏志曰，毌丘儉遣王頎追句驪王宮，窮沃沮東界，問其耆老所傳云。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-003-1', 'p0065', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '遣幽州刺史毌丘儉率諸軍及鮮卑、烏丸屯遼東南界，璽書徵公孫淵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-003-2', 'p0065', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '」毌丘儉志記云，時以儉為宣王副也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-004-3', 'p0065', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '七年春二月，幽州刺史毌丘儉討高句驪，夏五月，討濊貊，皆破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-004-4', 'p0065', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '冬十一月，詔征南大將軍王昶、征東將軍胡遵、鎮南將軍毌丘儉等征吳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-004-5', 'p0065', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '漢晉春秋曰：毌丘儉、王昶聞東軍敗，各燒屯走。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-004-6', 'p0065', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '」乃使郭淮、陳泰悉關中之衆，解狄道之圍；勑毌丘儉等案兵自守，以新城委吳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-004-7', 'p0065', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '會毌丘儉代誕，遂使特屯守合肥新城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-004-8', 'p0065', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '六年春二月己丑，鎮東將軍毌丘儉上言：「昔諸葛恪圍合肥新城，城中遣士劉整出圍傳消息，為賊所得，考問所傳，語整曰：『諸葛公欲活汝，汝可具服。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-004-9', 'p0065', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '二年春正月乙丑，鎮東將軍毌丘儉、楊州刺史文欽反。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-005-10', 'p0065', 'sanguozhi', 'a04-005', '《三國志·魏書五》', '毌丘儉、鍾會等作亂，咸假其命而以為辭焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-008-11', 'p0065', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '景初元年，乃遣幽州刺史毌丘儉等齎璽書徵淵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-012-12', 'p0065', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '時毌丘儉孫女適劉氏，以孕繫廷尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-013-13', 'p0065', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '正元中，毌丘儉、文欽反，毓持節至揚、豫州班行赦令，告諭士民，還為尚書。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-013-14', 'p0065', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '」明年春，鎮東將軍毌丘儉、揚州刺史文欽反，景王謂肅曰：「霍光感夏侯勝之言，始重儒學之士，良有以也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-014-15', 'p0065', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '干寶晉紀曰：毌丘儉之起也，大將軍以問陶，陶荅依違。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-021-16', 'p0065', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '世語曰：毌丘儉反，康有力，且欲起兵應之，以問山濤，濤曰：「不可。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-021-17', 'p0065', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '蓋緣世語云康欲舉兵應毌丘儉，故謂破儉便應殺康也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-021-18', 'p0065', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '尋文王以景元四年鍾、鄧平蜀後，始授相國位；若巽為相國掾時陷安，焉得以破毌丘儉年殺嵇、呂？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-021-19', 'p0065', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '摯與毌丘儉鄉里相親，故為詩與儉，求仙人藥一丸，欲以感切儉求助也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-021-20', 'p0065', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '征南大將軍王昶、征東將軍胡遵、鎮南將軍毌丘儉等表請征吳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-021-21', 'p0065', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '正元二年春，毌丘儉、文欽作亂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-022-22', 'p0065', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '幽州刺史毌丘儉上疏曰：「陛下即位已來，未有可書。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-022-23', 'p0065', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '毌丘儉作亂，大將軍司馬景王出征，毓綱紀後事，加侍中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-027-24', 'p0065', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '毌丘儉、文欽作亂，引兵拒儉、欽有功，封二子亭侯、關內侯，進位驃騎將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-027-25', 'p0065', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '毌丘儉、文欽作亂，以基為行監軍、假節，統許昌軍，適與景王會於許昌。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-028-26', 'p0065', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '毌丘儉字仲恭，河東聞喜人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-028-27', 'p0065', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '世語曰：毌丘儉之誅，黨與七百餘人，傳侍御史杜友治獄，惟舉首事十人，餘皆奏散。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-028-28', 'p0065', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '習鑿齒曰：毌丘儉感明帝之顧命，故為此役。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-028-29', 'p0065', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '君子謂毌丘儉事雖不成，可謂忠臣矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-028-30', 'p0065', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '」若毌丘儉可謂能不愧也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-028-31', 'p0065', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '前與毌丘儉、郭淮等俱舉義兵，當共討師，埽除凶孽，誠臣慺慺愚管所執。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-028-32', 'p0065', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '會誕去兵，毌丘儉往，乃陰共結謀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-028-33', 'p0065', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '後毌丘儉、文欽反，遣使詣誕，招呼豫州士民。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-028-34', 'p0065', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '誕旣與玄、颺等至親，又王淩、毌丘儉累見夷滅，懼不自安，傾帑藏振施以結衆心，厚養親附及揚州輕俠者數千人為死士。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-028-35', 'p0065', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '毌丘儉作亂，遣健步齎書，欲疑惑大衆，艾斬之，兼道進軍，先趣樂嘉城，作浮橋。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-028-36', 'p0065', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '毌丘儉作亂，大將軍司馬景王東征，會從，典知密事，衞將軍司馬文王為大軍後繼。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-028-37', 'p0065', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '評曰：王淩風節格尚，毌丘儉才識拔幹，諸葛誕嚴毅威重，鍾會精練策數，咸以顯名，致茲榮任，而皆心大志迂，不慮禍難，變如發機，宗族塗地，豈不謬惑邪！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-029-38', 'p0065', 'sanguozhi', 'a04-029', '《三國志·魏書二十九》', '輅隨軍西行，過毌丘儉墓下，倚樹哀吟，精神不樂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-030-39', 'p0065', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '魏畧曰：景初元年秋，遣幽州刺史毌丘儉率衆軍討遼東。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-030-40', 'p0065', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '正始中，幽州刺史毌丘儉討句麗，遣玄菟太守王頎詣夫餘，位居遣大加郊迎，供軍糧。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-030-41', 'p0065', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '正始三年，宮寇西安平，其五年，為幽州刺吏毌丘儉所破。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-030-42', 'p0065', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '毌丘儉討句麗，句麗王宮奔沃沮，遂進師擊之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-048-43', 'p0065', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '十二月朔丙申，大風雷電，魏使將軍諸葛誕、胡遵等步騎七萬圍東興，將軍王昶攻南郡，毌丘儉向武昌。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-048-44', 'p0065', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '二年春正月，魏鎮東將軍毌丘儉、前將軍文欽以淮南之衆西入，戰于樂嘉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-064-45', 'p0065', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '二年，魏將毌丘儉、文欽以衆叛，與魏人戰于樂嘉，峻帥驃騎將軍呂據、左將軍留贊襲壽春，會欽敗降，軍還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a05-002-46', 'p0065', 'jinshu', 'a05-002', '《晉書·卷二》', '諸葛誕、毌丘儉、王昶、陳泰、胡遵都督四方，王基、州泰、鄧艾、石苞典州郡，盧毓、李豐掌選舉，傅嘏、虞松參計謀，鍾會、夏侯玄、王肅、陳本、孟康、趙酆、張緝預朝議，四海傾注，朝野肅然。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a05-002-47', 'p0065', 'jinshu', 'a05-002', '《晉書·卷二》', '帝於是使鎮東將軍毌丘儉、揚州刺史文欽等距之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a05-002-48', 'p0065', 'jinshu', 'a05-002', '《晉書·卷二》', '毌丘儉、文欽之亂，大軍東征，帝兼中領軍，留鎮洛陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a05-002-49', 'p0065', 'jinshu', 'a05-002', '《晉書·卷二》', '議者請速伐之，帝曰：「誕以毌丘儉輕疾傾覆，今必外連吳寇，此為變大而遲。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a05-013-50', 'p0065', 'jinshu', 'a05-013', '《晉書·卷十三》', '鎮東大將軍毌丘儉等據淮南叛，景帝討平之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a05-013-51', 'p0065', 'jinshu', 'a05-013', '《晉書·卷十三》', '是以毌丘儉以孛為己應，遂起兵而敗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a05-037-52', 'p0065', 'jinshu', 'a05-037', '《晉書-卷三十七・列傳第七》', '孚次壽春，遣毌丘儉、文欽等進討。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a05-039-53', 'p0065', 'jinshu', 'a05-039', '《晉書-卷三十九・列傳第九》', '」毌丘儉、文欽果不服，舉兵反。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a05-040-54', 'p0065', 'jinshu', 'a05-040', '《晉書-卷四十・列傳第十》', '參大將軍軍事，從景帝討毌丘儉、文欽於樂嘉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a05-040-55', 'p0065', 'jinshu', 'a05-040', '《晉書-卷四十・列傳第十》', '時沛國劉含母，及帝舅羽林監王虔前妻，皆毌丘儉孫女。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a04-004-0', 'p0066', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '二年春正月乙丑，鎮東將軍毌丘儉、楊州刺史文欽反。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a04-009-1', 'p0066', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '奏使郭太后出居別宮，及遣樂安王使北詣鄴，又遣文欽令還淮南，皆謐之計。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a04-013-2', 'p0066', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '正元中，毌丘儉、文欽反，毓持節至揚、豫州班行赦令，告諭士民，還為尚書。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a04-013-3', 'p0066', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '」明年春，鎮東將軍毌丘儉、揚州刺史文欽反，景王謂肅曰：「霍光感夏侯勝之言，始重儒學之士，良有以也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a04-021-4', 'p0066', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '正元二年春，毌丘儉、文欽作亂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a04-027-5', 'p0066', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '毌丘儉、文欽作亂，引兵拒儉、欽有功，封二子亭侯、關內侯，進位驃騎將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a04-027-6', 'p0066', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '毌丘儉、文欽作亂，以基為行監軍、假節，統許昌軍，適與景王會於許昌。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a04-027-7', 'p0066', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '時兖州刺史鄧艾屯樂嘉，儉使文欽將兵襲艾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a04-027-8', 'p0066', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '文欽、唐咨，舉吳重兵，昧利壽春，身歿不反。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a04-028-9', 'p0066', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '吳太傅諸葛恪圍合肥新城，儉與文欽禦之，太尉司馬孚督中軍東解圍，恪退還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a04-028-10', 'p0066', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '揚州刺史前將軍文欽，曹爽之邑人也，驍果麄猛，數有戰功，好增虜獲，以徼寵賞，多不見許，怨恨日甚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a04-028-11', 'p0066', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '大目知大將軍一目已突出，啟云：「文欽本是明公腹心，但為人所誤耳，又天子鄉里。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a04-028-12', 'p0066', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '大目昔為文欽所信，乞得追解語之，令還與公復好。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a04-028-13', 'p0066', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '」大將軍聽遣大目單身往，乘大馬，被鎧冑，追文欽，遙相與語。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a04-028-14', 'p0066', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '後毌丘儉、文欽反，遣使詣誕，招呼豫州士民。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a04-028-15', 'p0066', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '吴大將孫峻、呂據、留贊等聞淮南亂，會文欽往，乃帥衆將欽徑至壽春；時誕諸軍已至，城不可攻，乃走。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a04-028-16', 'p0066', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '吴人大喜，遣將全懌、全端、唐咨、王祚等，率三萬衆，密與文欽俱來應誕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a04-028-17', 'p0066', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '」文欽曰：「江東乘戰勝之威乆矣，未有難北方者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a04-028-18', 'p0066', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '漢晉春秋曰：文欽曰：「蔣班、焦彝謂我不能出而走，全端、全懌又率衆逆降，此敵無備之時也，可以戰矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a04-028-19', 'p0066', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '」乃赦鴦、虎，使將兵數百騎馳巡城，呼語城內云：「文欽之子猶不見殺，其餘何懼？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a04-028-20', 'p0066', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '文欽日祠祭事天，斬於人手。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a04-028-21', 'p0066', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '文欽以後大軍破敗於城下，艾追之至丘頭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a04-028-22', 'p0066', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '文欽、唐咨為國大害，叛主讎賊，還為戎首。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a04-047-23', 'p0066', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '冬十月，魏將文欽偽叛以誘朱異，權遣呂據就異以迎欽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a04-048-24', 'p0066', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '二年春正月，魏鎮東將軍毌丘儉、前將軍文欽以淮南之衆西入，戰于樂嘉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a04-048-25', 'p0066', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '峻用征北大將軍文欽計，將征魏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a04-048-26', 'p0066', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '六月，使文欽、唐咨、全端等步騎三萬救誕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a04-048-27', 'p0066', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '三年春正月，諸葛誕殺文欽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a04-055-28', 'p0066', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '魏將文欽來降，以奉為虎威將軍，從孫峻至壽春迎之，與敵追軍戰於高亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a04-056-29', 'p0066', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '綝聞之，使中書奉詔，詔文欽、劉纂、唐咨等使取據，又遣從兄憲以都下兵逆據於江都。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a04-056-30', 'p0066', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '魏廬江太守文欽營住六安，多設屯砦，置諸道要，以招誘亡叛，為邊寇害。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a04-056-31', 'p0066', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '」十三年，文欽詐降，密書與異，欲令自迎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a04-064-32', 'p0066', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '二年，魏將毌丘儉、文欽以衆叛，與魏人戰于樂嘉，峻帥驃騎將軍呂據、左將軍留贊襲壽春，會欽敗降，軍還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a04-064-33', 'p0066', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '其明年，文欽說峻征魏，峻使欽與呂據、車騎劉纂、鎮南朱異、前將軍唐咨自江都入淮、泗，以圖青、徐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a04-064-34', 'p0066', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '綝聞之，遣從兄慮將兵逆據於江都，使中使勑文欽、劉纂、唐咨等合衆擊據，遣侍中左將軍華融、中書丞丁晏告胤取據，并喻胤宜速去意。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a04-064-35', 'p0066', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '吳遣文欽、唐咨、全端、全懌等帥三萬人救之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a04-064-36', 'p0066', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '朱異帥三萬人屯安豐城，為文欽勢。');
